/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({api,event}) {
    var parameters = [];
    var configs = api.state.configs;
    var sys_cs_collab_settings = configs.sys_cs_collab_settings;
    var collab_chat_webhook_registry = configs.collab_chat_webhook_registry;
    var sys_cs_collab_provider_application = configs.sys_cs_collab_provider_application;
    var oAuthEntity = configs.oAuthEntity;
    var inputs = api.state.inputs;

    parameters.push({
        field: "app_id",
        value: inputs.teams_app_id,
        name: "sys_cs_collab_provider_application",
        sysId: sys_cs_collab_provider_application.sys_id
    });

    parameters.push({
        field: "setup_status",
        value: "error",
        name: "sys_cs_collab_provider_application",
        sysId: sys_cs_collab_provider_application.sys_id
    });

    parameters.push({
        field: "redirect_url",
        value: inputs.redirect_url,
        name: "sys_cs_collab_provider_application",
        sysId: sys_cs_collab_provider_application.sys_id
    });

    parameters.push({
        field: "callback_url",
        value: inputs.callback_url,
        name: "collab_chat_webhook_registry",
        sysId: collab_chat_webhook_registry.sys_id
    });

    parameters.push({
        field: "enable_teams",
        value: api.state.isTeamsEnabled,
        name: "sys_cs_collab_settings",
        sysId: sys_cs_collab_settings.sys_id
    });

    if (api.state.isTeamsEnabled) {
        parameters.push({
            field: "enable_slack",
            value: false,
            name: "sys_cs_collab_settings",
            sysId: sys_cs_collab_settings.sys_id
        });
        // Change preference channel to Teams
        parameters.push({
            field: "preference_channel",
            value: "a812eaf8c32111100f24c87af040dd59",
            name: "sys_cs_collab_settings",
            sysId: sys_cs_collab_settings.sys_id
        });
    }

    parameters.push({
        field: "client_secret",
        value: inputs.client_secret,
        name: "oauth_entity",
        sysId: oAuthEntity.sys_id
    });

    return {
        parameters: parameters
    };
}

